import SwiftUIstruct TasksView: View {    @StateObject var viewModel: TasksViewModel    let primaryBackground = Color(red: 28/255, green: 28/255, blue: 30/255)    let cardBackgroundColor = Color(red: 44/255, green: 44/255, blue: 46/255)    let accentColor = Color(red: 255/255, green: 87/255, blue: 51/255)    var body: some View {        ZStack {            primaryBackground.ignoresSafeArea()            ScrollView {                VStack(spacing: 20) {                    Text("Tareas")                        .font(.largeTitle.bold())                        .foregroundColor(.white)                        .frame(maxWidth: .infinity, alignment: .leading)                        .padding(.horizontal)                        .padding(.top)                    let grouped = viewModel.groupedTasks                    ForEach(grouped.keys.sorted(), id: \.self) { subject in                        VStack(alignment: .leading, spacing: 16) {                            Text(subject)                                .font(.title2.bold())                                .foregroundColor(.white)                                .padding(.horizontal)                            VStack(spacing: 28) {                                ForEach(grouped[subject]!) { task in                                    TimelineTaskRow(                                        task: task,                                        toggle: { viewModel.toggleTask(task) }                                    )                                }                            }                            .padding(.leading, 28)                        }                    }                }                .padding(.bottom)            }        }        .preferredColorScheme(.dark)    }}